Clase GitRunner que encapsula la ejecución de comandos:

export class GitRunner {
  constructor(private readonly cwd: string) {}

  private run(args: string[]): string | null {
    try {
      return execSync(`git ${args.join(' ')}`, {
        cwd: this.cwd,
        encoding: 'utf-8',
        stdio: ['pipe', 'pipe', 'pipe'],
        timeout: 5000
      }).trim();
    } catch {
      return null;
    }
  }

  isGitRepo(): boolean {
    return this.run(['rev-parse', '--git-dir']) !== null;
  }

  getCurrentBranch(): string | null {
    return this.run(['branch', '--show-current']);
  }

  getRecentCommits(limit: number): CommitInfo[] {
    const raw = this.run(['log', `--max-count=${limit}`, '--pretty=format:%h|%an|%ar|%s']);
    if (!raw) return [];
    return raw.split('\n').map(line => {
      const [hash, author, date, ...msgParts] = line.split('|');
      return { hash, author, date, message: msgParts.join('|') };
    });
  }

  getStatus(): string[] {  // lista de archivos con cambios
    const raw = this.run(['status', '--porcelain']);
    return raw ? raw.split('\n').filter(Boolean) : [];
  }

  getRemoteUrl(): string | null {
    const raw = this.run(['remote', 'get-url', 'origin']);
    if (!raw) return null;
    // Sanitizar tokens de la URL
    return raw.replace(/https:\/\/[^@]+@/, 'https://');
  }

  getContributors(): string[] {
    const raw = this.run(['log', '--pretty=format:%an', '--no-duplicates']);
    if (!raw) return [];
    return [...new Set(raw.split('\n').filter(Boolean))];
  }
}

interface CommitInfo {
  hash: string;
  author: string;
  date: string;
  message: string;
}

interface GitContextData {
  isGitRepo: boolean;
  currentBranch: string | null;
  recentCommits: CommitInfo[];
  modifiedFiles: string[];
  contributors: string[];
  remoteUrl: string | null;
}

export interface GitAdapterOptions {
  projectRoot: string;
  maxCommits?: number;  // default: 10
}

export class GitAdapter implements ContextSource {
  private runner: GitRunner;
  private maxCommits: number;

  constructor(options: GitAdapterOptions) {
    this.runner = new GitRunner(path.resolve(options.projectRoot));
    this.maxCommits = options.maxCommits ?? 10;
  }

  getName(): string { return 'GitAdapter'; }

  async collect(): Promise<ContextData> {
    const isGitRepo = this.runner.isGitRepo();

    const data: GitContextData = {
      isGitRepo,
      currentBranch: isGitRepo ? this.runner.getCurrentBranch() : null,
      recentCommits: isGitRepo ? this.runner.getRecentCommits(this.maxCommits) : [],
      modifiedFiles: isGitRepo ? this.runner.getStatus() : [],
      contributors: isGitRepo ? this.runner.getContributors() : [],
      remoteUrl: isGitRepo ? this.runner.getRemoteUrl() : null,
    };

    return {
      type: 'git',
      source: this.getName(),
      timestamp: new Date().toISOString(),
      priority: ContextPriority.High,
      data: data as unknown as Record<string, unknown>,
    };
  }
}
